"""Build the offline review gallery after capture_design.dart finishes."""
from pathlib import Path
import json

out = Path(__file__).resolve().parents[3] / 'docs/screenshots/identity-v4'
entries = json.loads((out / 'manifest.json').read_text())
entries.sort(key=lambda e: (e['name'], e['theme'] != 'light'))
page = r'''<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>LocalJam · Design review</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#faf8f5;color:#292428;font:16px/1.5 system-ui,sans-serif}header,main{max-width:1440px;margin:auto;padding:32px}h1{font-size:38px;letter-spacing:-1.4px;margin:8px 0}p{max-width:820px;color:#71686d}header{padding-bottom:12px}.brand{color:#b82f59;font-weight:700}.controls{position:sticky;top:0;z-index:1;background:#faf8f5f5;border-bottom:1px solid #ded8d5;padding:16px 32px;display:flex;gap:12px;flex-wrap:wrap}input,select,button{font:inherit;border:1px solid #c9bfc3;border-radius:10px;padding:10px 14px;background:#fffefc;color:inherit}input{min-width:260px;flex:1}button{cursor:pointer}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:28px}.card{margin:0;min-width:0}.preview{display:flex;align-items:center;justify-content:center;background:#eee9e5;border:1px solid #e2dcd8;border-radius:18px;overflow:hidden;height:440px;text-decoration:none}.preview img{max-width:100%;max-height:100%;object-fit:contain}figcaption{padding:10px 2px;font-weight:600;font-size:15px}.meta{display:block;font-size:13px;color:#71686d;font-weight:400}#count{margin:0 0 24px}dialog{border:0;border-radius:16px;background:#211e21;color:#f7f2ee;max-width:96vw;max-height:96vh;padding:14px}dialog::backdrop{background:#000b}dialog img{display:block;max-width:90vw;max-height:80vh;margin:10px auto;object-fit:contain}.dialogbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.dialogbar span{flex:1}dialog a{color:#f28aa7}dialog button{background:#302b2f;color:#f7f2ee}.empty{padding:30px}details{max-width:860px;color:#71686d;margin:16px 0}summary{cursor:pointer;color:#292428}a{color:#b82f59}@media(max-width:600px){header,main{padding:20px}.controls{padding:12px 20px}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.preview{height:330px}h1{font-size:30px}}
</style>
<header><span class="brand">LocalJam / Identity v4</span><h1>Your music. Better together.</h1>
<p>A song-first design with warm surfaces, Manrope headings, raspberry accents, and a quieter social layer. Each image is an individual screen or state rendered from the production Flutter widgets.</p>
<details><summary>Capture coverage and limitations</summary><p>Includes onboarding, Nearby, hosting, player and queue, people and invites, settings and licenses, history, music library, permission explanations, scanner errors, session recovery, guest permissions, downloads, audio interruption, and responsive layouts. Each state appears in light and dark mode.</p><p>Fixture songs and original generated cover art; native audio and device services mocked. Guest sessions use a real local host/client connection, and the host-away view comes from the host&rsquo;s own away announcement; transfer progress and failure use deterministic state. Past Jams reads its covers back out of tagged fixture files, as on a device. These are widget renders, not device screenshots. Live camera, OS permission prompts, native file/share pickers, hardware audio, and every possible transient/network combination are outside this capture set. Larger scrollable pages show their captured viewport.</p><p>Open any image to inspect it, then use arrow keys to move through the current filter. Escape closes the viewer. PNGs are captured at 2× resolution.</p></details></header>
<div class="controls"><input id="search" type="search" placeholder="Find a page or state…" aria-label="Find a page or state"><select id="theme" aria-label="Theme"><option value="all">Both themes</option><option value="light">Light</option><option value="dark">Dark</option></select><select id="group" aria-label="Category"><option value="all">All pages and states</option><option value="main">Main pages</option><option value="player">Player & queue</option><option value="social">People & invitations</option><option value="errors">Errors & permissions</option><option value="guest">Guest states</option><option value="stress">Long names, many people, large text</option></select></div>
<main><p id="count"></p><div class="grid" id="grid"></div></main>
<dialog id="viewer"><div class="dialogbar"><button id="prev" aria-label="Previous image">←</button><span id="caption"></span><button id="next" aria-label="Next image">→</button><a id="original" target="_blank">Open PNG</a><button id="close">Close</button></div><img id="full" alt=""></dialog>
<script>
const entries=ENTRIES;
const grid=document.getElementById('grid'), viewer=document.getElementById('viewer');
let visible=[],current=0;
function title(e){return e.name.replace(/^\d+-/,'').replaceAll('-',' ').replace(/^./,s=>s.toUpperCase());}
const groups={main:[1,5,9,12,13,14,16,25,35],player:[15,16,17,18,19,20,26,27,28,29,30,31],social:[21,22,23,24,41],errors:[3,7,23,29,32,33,34,43,44,45],guest:[38,39,40,41,42,43,44,45],stress:[29,46,47,48,49]};
function render(){const q=document.getElementById('search').value.toLowerCase(),t=document.getElementById('theme').value,g=document.getElementById('group').value;
visible=entries.filter(e=>(t==='all'||e.theme===t)&&(g==='all'||groups[g].includes(parseInt(e.name)))&&(title(e)+' '+e.theme).toLowerCase().includes(q));grid.replaceChildren();
document.getElementById('count').textContent=`${visible.length} of ${entries.length} captures · ${new Set(entries.map(e=>e.name)).size} states across two themes`;
visible.forEach((e,i)=>{const fig=document.createElement('figure');fig.className='card';const a=document.createElement('a');a.className='preview';a.href=e.file;a.onclick=ev=>{ev.preventDefault();open(i)};const img=document.createElement('img');img.src=e.file;img.alt=title(e)+' — '+e.theme;img.loading='lazy';a.append(img);const c=document.createElement('figcaption');c.textContent=title(e);const m=document.createElement('span');m.className='meta';m.textContent=`${e.theme} · ${e.width} × ${e.height}`;c.append(m);fig.append(a,c);grid.append(fig)});}
function open(i){current=(i+visible.length)%visible.length;const e=visible[current];document.getElementById('full').src=e.file;document.getElementById('full').alt=title(e)+' — '+e.theme;document.getElementById('caption').textContent=title(e)+' · '+e.theme;document.getElementById('original').href=e.file;if(!viewer.open)viewer.showModal();}
document.getElementById('close').onclick=()=>viewer.close();document.getElementById('prev').onclick=()=>open(current-1);document.getElementById('next').onclick=()=>open(current+1);document.addEventListener('keydown',e=>{if(viewer.open&&e.key==='ArrowRight')open(current+1);if(viewer.open&&e.key==='ArrowLeft')open(current-1)});for(const id of ['search','theme','group'])document.getElementById(id).addEventListener('input',render);render();
</script></html>'''
(out / 'index.html').write_text(page.replace('ENTRIES', json.dumps(entries)))
print(f'Gallery: {len(entries)} captures')
